export const featuredProperties = catalogData.properties.slice(0, 4);
export const catalogCategories = ['Квартиры', 'Новостройки', 'Дома', 'Коммерческая', 'Участки'];
// Reuse the office contact from the existing Orenburg mockup.
const officePhone = catalogData.contacts.phones[1].replace(/^8/, '+7');
const phoneLink = (className) => `<a class="${className}" href="tel:${officePhone.replace(/[^+\d]/g, '')}">${esc(officePhone)}</a>`;
export const icon = (name, className='') => {
  const paths = {
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    diagonal:'<path d="M6 18 18 6M6 6h12v12"/>',
    back:'<path d="M19 12H5m6-6-6 6 6 6"/>',
    search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
    phone:'<path d="m8 3 3 5-3 3a15 15 0 0 0 5 5l3-3 5 3c0 3-2 5-5 5C9 21 3 15 3 8c0-3 2-5 5-5Z"/>',
    message:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5a9.5 9.5 0 0 1 19 0Z"/><path d="M7 10h9M7 14h6"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    menu:'<path d="M4 8h16M4 16h16"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
  };
  return `<svg class="ui-icon ${className}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.arrow}</svg>`;
};
export const cta = (label, topic=label, secondary=false) => `<button class="r-button ${secondary?'r-button-secondary':''}" data-consult="${esc(topic)}"><span>${esc(label)}</span><span class="button-icon">${icon('diagonal')}</span></button>`;
export const sectionHead = (number, chapter, title, description='') => `<div class="r-section-head"><div><p class="r-kicker"><span class="section-number">${number}</span> ${esc(chapter)}</p><h2>${title}</h2></div>${description?`<p class="r-section-description">${description}</p>`:''}</div>`;
export const contactGroup = () => `<div class="contact-group" role="group" aria-label="Связаться с агентством"><button data-consult="Вопрос агенту" aria-label="Задать вопрос агенту">${icon('message')}</button><button data-consult="Заказать звонок" aria-label="Заказать звонок">${icon('phone')}</button></div>`;

export function refreshHeader({theme='dark',current=''}={}){return `<header class="r-header r-container${theme==='light'?' r-header-light':''}"><a class="r-brand" href="homepage.html" aria-label="Квадрат — главная">${image(art(theme==='light'?'logo-dark.svg':'logo.svg'),'Квадрат — агентство недвижимости','', 'width="190" height="99"')}</a><nav class="r-navigation" id="primary-navigation" aria-label="Основная навигация"><a href="property-catalog.html"${current==='catalog'?' aria-current="page"':''}>Недвижимость</a><a href="#services">Услуги</a><a href="#news">Квадрат изнутри</a><a href="#blog">Статьи</a><a href="contacts.html"${current==='contacts'?' aria-current="page"':''}>Контакты</a></nav><div class="header-actions">${phoneLink('header-phone')}${contactGroup()}<button class="menu-toggle" aria-expanded="false" aria-controls="primary-navigation" aria-label="Открыть меню">${icon('menu')}</button></div></header>`;}
export function refreshHero(){return `<div class="r-intro ruled-dark">${image(photo('0f3b9ff0a9e2ef25.jpg'),'','hero-architecture','fetchpriority="high" width="2000" height="1125"')}${refreshHeader()}<section class="r-hero r-container" aria-labelledby="hero-title"><div class="r-hero-copy"><p class="r-kicker"><span class="location-dot"></span> Агентство недвижимости · Оренбург</p><h1 id="hero-title">Недвижимость<br><span>в Оренбурге</span></h1><p class="r-hero-description">Поможем купить, продать или сдать недвижимость.<br> Подберём объекты, организуем просмотры и сопроводим сделку.</p><div class="r-hero-actions"><a class="r-button" href="#search"><span>Найти недвижимость</span><span class="button-icon">${icon('diagonal')}</span></a><a class="hero-about-link" href="#news">Квадрат изнутри ${icon('arrow')}</a></div></div><div class="hero-side-note"><span class="tiny-cross" aria-hidden="true">+</span><p>Подбор объектов.<br>Подготовка документов.<br>Сопровождение сделки.</p><span class="hero-note-line"></span><small>Агентство «Квадрат»</small></div><div class="hero-bottom"><span>Покупка · Продажа · Аренда</span><a href="#search">Перейти к поиску ${icon('arrow')}</a></div></section>${refreshSearch()}</div>`;}
export function refreshSearch(){return `<section class="r-search r-container" id="search" aria-labelledby="search-title"><div class="search-heading"><h2 id="search-title">Поиск недвижимости</h2><span>Выберите тип объекта, число комнат и район.</span></div><form action="property-catalog.html" method="get" class="property-search" aria-label="Подбор недвижимости">${searchFields()}<button class="r-button search-button" type="submit">${icon('search')}<span>Найти объекты</span></button></form><div class="search-suggestions"><span>Быстрый поиск</span><a href="property-catalog.html?deal=buy&amp;type=flat&amp;market=secondary&amp;rooms=1">Однокомнатные квартиры ${icon('diagonal')}</a><a href="property-catalog.html?deal=buy&amp;type=flat&amp;market=secondary&amp;rooms=3">Трёхкомнатные квартиры ${icon('diagonal')}</a><button data-consult="Подбор недвижимости">Подбор с агентом ${icon('diagonal')}</button></div></section>`;}
export function refreshCatalog(){return `<section class="r-catalog r-section r-container" id="catalog">${sectionHead('01','Покупка и аренда','Каталог недвижимости','Квартиры, дома, участки и коммерческие помещения. Сравните цены, площадь и расположение.')}<div class="catalog-toolbar"><div class="catalog-tabs ui-segments" role="tablist" aria-label="Тип недвижимости">${catalogCategories.map((label,i)=>`<button class="ui-segment" role="tab" id="category-${i}" aria-controls="property-list" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-category="${i}">${label}</button>`).join('')}</div><a class="r-text-link" href="property-catalog.html">Весь каталог ${icon('diagonal')}</a></div><div id="property-list" role="tabpanel" aria-labelledby="category-0" tabindex="0"><div class="property-grid">${featuredProperties.map(compactPropertyCard).join('')}</div><p class="catalog-message" role="status" hidden></p></div><div class="catalog-bottom"><p>Объекты и цены из исходного макета</p><div class="carousel-controls"><span class="carousel-position" aria-live="polite">01 / 04</span><div class="carousel-arrows" role="group" aria-label="Карточки недвижимости"><button data-carousel="catalog" data-step="-1" aria-label="Предыдущая карточка">${icon('back')}</button><button data-carousel="catalog" data-step="1" aria-label="Следующая карточка">${icon('arrow')}</button></div></div></div><aside class="personal-selection" id="consultation"><div class="selection-mark" aria-hidden="true">${image(art('home.svg'))}</div><div><h3>Подбор недвижимости с агентом</h3><p>Укажите бюджет, район и требования к объекту. Подберём варианты и организуем просмотры.</p></div><div class="selection-actions">${cta('Заказать подбор','Подбор недвижимости')}${contactGroup()}</div></aside></section>`;}
export function promotionSlide(item, index=0, count=1){
  return `<article class="promotion-slide" id="promotion-${esc(item.id)}" role="group" aria-roledescription="слайд" aria-label="${index+1} из ${count}"${index?' hidden':''}><div class="promotion-copy"><div class="promotion-title-block"><p class="promotion-tag"><span aria-hidden="true"></span>${esc(item.label)}</p><h3>${esc(item.title)}</h3></div><div class="promotion-details"><p class="promotion-description">${esc(item.description)}</p>${item.note?`<p class="promotion-note">${esc(item.note)}</p>`:''}</div></div><div class="promotion-image">${image(item.image,item.imageAlt,'','loading="lazy" width="464" height="222"')}<div class="promotion-action"><a class="r-button" href="${esc(item.href)}"><span>${esc(item.actionLabel)}</span><span class="button-icon">${icon('diagonal')}</span></a></div></div></article>`;
}
export function refreshPromotions(items=promotions){
  if(!items.length)return '<span id="offers" class="promotion-empty-anchor" aria-hidden="true"></span>';
  const multiple=items.length>1;
  return `<section class="r-promotions r-container r-section" id="offers" data-promotion-carousel aria-label="Акции и предложения" aria-roledescription="карусель"><div class="promotion-section-head"><div><p class="r-kicker"><span class="section-number">02</span> Специальные условия</p><h2>Акции и предложения</h2></div><div class="promotion-controls"${multiple?'':' hidden'}><span class="promotion-position" data-promotion-position aria-hidden="true">01 / ${String(items.length).padStart(2,'0')}</span><div class="promotion-pagination" role="group" aria-label="Выбрать предложение">${items.map((item,index)=>`<button type="button" data-promotion-dot="${index}" aria-current="${index===0}" aria-controls="promotion-${esc(item.id)}" aria-label="Показать предложение ${index+1}: ${esc(item.label)}"><span></span></button>`).join('')}</div><div class="carousel-arrows" role="group" aria-label="Переключение предложений"><button type="button" data-promotion-prev aria-label="Предыдущее предложение">${icon('back')}</button><button type="button" data-promotion-next aria-label="Следующее предложение">${icon('arrow')}</button></div></div></div><div class="promotion-surface"><div class="promotion-slides">${items.map((item,index)=>promotionSlide(item,index,items.length)).join('')}</div></div><p class="sr-only" data-promotion-status role="status" aria-live="polite" aria-atomic="true"></p></section>`;
}

