export function refreshClosing(){return `<section class="r-closing ruled-dark" id="conversation"><div class="r-container"><div class="closing-top"><p class="r-kicker">Покупателям и собственникам</p><span class="closing-mark" aria-hidden="true">↗</span></div><h2>Консультация<br><span>специалиста</span></h2><div class="closing-bottom"><p>Расскажите, что планируете купить, продать или сдать. Уточним детали и расскажем о порядке работы.</p><div class="selection-actions">${cta('Заказать консультацию','Консультация специалиста')}${contactGroup()}</div></div></div></section>`;}
export function refreshFooter(){return `<footer class="r-footer" id="contacts"><div class="r-container"><div class="footer-top"><a class="r-brand" href="homepage.html">${image(art('logo-dark.svg'),'Квадрат — агентство недвижимости','', 'width="190" height="99" loading="lazy"')}</a><p>Агентство недвижимости<br>в Оренбурге</p><div class="footer-contact-details"><span>Связаться с агентством</span>${phoneLink('footer-phone')}</div></div><div class="footer-nav"><nav aria-label="Недвижимость"><h3>Недвижимость</h3><a href="property-catalog.html">Квартиры</a><a href="property-catalog.html?market=new">Новостройки</a><a href="property-catalog.html?type=house">Дома</a></nav><nav aria-label="Услуги агентства"><h3>Услуги</h3><a href="#services">Покупка и продажа</a><a href="#mortgage">Ипотека</a><button data-consult="Юридическое сопровождение">Сопровождение сделки</button></nav><nav aria-label="Квадрат"><h3>Компания</h3><a href="#news">Квадрат изнутри</a><a href="#blog">Статьи</a><a href="#offers">Акции и предложения</a><a href="contacts.html">Контакты</a></nav><div class="footer-note"><p>Оренбург</p><span>Консультации по подбору,<br>продаже и оформлению недвижимости.</span>${contactGroup()}</div></div><div class="footer-bottom"><p>© Квадрат, 2026</p><span>Концепция главной · данные демонстрационные</span><a href="index.html#pages">Все макеты ${icon('diagonal')}</a></div></div></footer>`;}
export function renderRefresh(){return `${refreshHero()}<div class="r-content">${refreshCatalog()}${refreshPromotions()}${refreshServices()}${refreshMortgage()}${refreshCompanyLife()}${refreshAbout()}${refreshJournal()}</div>${refreshClosing()}${refreshFooter()}${companyDialog()}`;}
